vulnerable_code:
namespace App\Policies;

use App\Models\User;
use App\Models\Beneficiary;

class BeneficiaryPolicy
{
    public function delete(User $user, Beneficiary $beneficiary): bool
    {
        // Faulty boolean operator: uses OR instead of AND, allowing any user to delete unlocked records
        return $beneficiary->status !== 'locked' || $user->id === $beneficiary->user_id;
    }
}

corrected_code:
namespace App\Policies;

use App\Models\User;
use App\Models\Beneficiary;

class BeneficiaryPolicy
{
    public function delete(User $user, Beneficiary $beneficiary): bool
    {
        return $user->id === $beneficiary->user_id && $beneficiary->status !== 'locked';
    }
}
